def seed():
    from .models import Place, Product, Service, Stay

    for i, p in enumerate(PLACES):
        Place.objects.update_or_create(slug=p["slug"], defaults={**{k: v for k, v in p.items() if k != "slug"}, "order": i})
    places = {p.slug: p for p in Place.objects.all()}
    for s in STAYS:
        d = {k: v for k, v in s.items() if k not in ("slug", "near")}
        d["near"] = places.get(s["near"])
        Stay.objects.update_or_create(slug=s["slug"], defaults=d)
    for s in SERVICES:
        Service.objects.update_or_create(slug=s["slug"], defaults={k: v for k, v in s.items() if k != "slug"})
    for p in PRODUCTS:
        Product.objects.update_or_create(slug=p["slug"], defaults={k: v for k, v in p.items() if k != "slug"})
    return Place.objects.count(), Stay.objects.count(), Service.objects.count(), Product.objects.count()
